package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*;import co.edu.cinematch.core.model.*;import co.edu.cinematch.core.repository.*;import java.time.*;
public class PagoService {private final Repository<Pago> repo;private final ReservaService reservas;public PagoService(Repository<Pago>r,ReservaService rs){repo=r;reservas=rs;}public Pago procesar(String reservaId,String metodoPago){Reserva reserva=reservas.buscar(reservaId);if(reserva.getAsientoIds().isEmpty())throw new ValidationException("La reserva debe tener al menos un asiento.");if(metodoPago==null||metodoPago.trim().isEmpty())throw new ValidationException("El método de pago es obligatorio.");Pago pago=new Pago(reservaId,metodoPago,reserva.getTotal(),LocalDateTime.now(),"APROBADO");reserva.setEstado(EstadoReserva.PAGADA);return repo.save(pago);}}
